const fs = require('node:fs');
const { pathToFileURL } = require('node:url');

async function main() {
  const sdk = await import(pathToFileURL('D:/develop/works/tombo-view-ask-policy/dist/index.js').href);
  const noteContent = fs.readFileSync('export-note.md', 'utf8');
  const passage = noteContent.trim();
  const hash = sdk.hashPassage(passage);

  const task = {
    schemaVersion: '0.1',
    taskId: 'task-export-workspace-deletion',
    goal: 'レポートを出力したあとworkspaceを削除した場合に24時間以内ならリンクからファイルを取れるか確認し説明する',
    mode: 'explain',
    successCriteria: [
      'export-note.mdの記述に基づき、workspace削除後のエクスポートダウンロード可否を正確に判断して説明する'
    ],
    evidence: [
      {
        id: 'ev-export-note-1',
        kind: 'document',
        locator: 'export-note.md',
        sourceGroup: 'local',
        retrievedAt: new Date().toISOString(),
        version: '1.0',
        scope: 'workspace',
        passage: passage,
        contentHash: hash,
        validity: 'current'
      }
    ],
    reflectionRequired: true,
    proposedAnswer: 'レポートを出力したあとworkspaceを削除した場合、24時間以内であってもリンクからファイルを取得することはできません。workspaceが削除されると、エクスポートおよびダウンロードリンクは即座に削除されます。',
    proposedActions: [],
    capabilities: [],
    budget: {
      maxRounds: 5,
      maxModelCalls: 5,
      maxToolCalls: 5,
      maxElapsedMs: 300000,
      maxInputChars: 100000,
      maxOutputTokensPerCall: 4000
    }
  };

  fs.writeFileSync('.session/task.json', JSON.stringify(task, null, 2), 'utf8');
  console.log('task.json written successfully. ContentHash:', hash);
}

main().catch(err => { console.error(err); process.exit(1); });
